@startuml
allowmixing
!theme plain
skinparam classAttributeIconSize 0

class UniversityUserBoundary <<Boundary>> {
  + searchCourseOfferings(criteria : SearchCriteria): SearchResult
  + viewCourseOfferingDetails(offeringId : guid): OfferingInfo
}

class StudentBoundary <<Boundary>> {
  + registerForOffering(offeringId : guid): RegistrationResult
  + viewSchedule(studentId : guid): StudentSchedule
  + exportSchedule(studentId : guid): ExportFile
  + dropRegistration(request : DropRegistrationRequest): DropRegistrationResponse
  + joinWaitlist(request : JoinWaitlistRequest): WaitlistEntry
  + viewOwnWaitlist(studentId : guid): list<WaitlistEntry>
  + cancelWaitlistEntry(studentId : guid, entryId : guid): void
}

class ProfessorBoundary <<Boundary>> {
  + requestAssignedOfferings(instructorId : guid): list<CourseOffering>
  + requestRoster(offeringId : guid): list<Student>
}

class AdminBoundary <<Boundary>> {
  + startTermManagement(): void
  + manageTerm(request : TermRequest): TermResult
  + handleManageOffering(request : ManageCourseOfferingRequest): ManageCourseOfferingResponse
}

class CourseOfferingSearchControl <<Control>> {
  + searchPublished(criteria : SearchCriteria): list<CourseOffering>
  + getOfferingDetails(offeringId : guid): OfferingInfo
}

class RegistrationControl <<Control>> {
  + handleRegistration(studentId : guid, offeringId : guid): RegistrationResult
  + validateEligibility(studentId : guid, offeringId : guid): ValidationResult
  + dropRegistration(request : DropRegistrationRequest): void
}

class ScheduleViewControl <<Control>> {
  + generateStudentSchedule(studentId : guid): StudentSchedule
  + generateScheduleExport(studentId : guid): ExportFile
}

class WaitlistControl <<Control>> {
  + processJoin(request : JoinWaitlistRequest): WaitlistEntry
  + retrieveStudentWaitlist(studentId : guid): list<WaitlistEntry>
  + attemptCancelEntry(studentId : guid, entryId : guid): boolean
}

class TermManagementControl <<Control>> {
  + startTermProcess(): void
  + handleTerm(request : TermRequest): TermResult
}

class CourseOfferingManagementControl <<Control>> {
  + manageOffering(request : ManageCourseOfferingRequest): ManageCourseOfferingResponse
  + validate(request : ManageCourseOfferingRequest): ValidationResult
}

class RosterReviewControl <<Control>> {
  + listAssignedOfferings(instructorId : guid): list<CourseOffering>
  + getRoster(offeringId : guid): list<Student>
}

class Student <<Entity>> {
  - studentId : guid
  - name : String
  - email : String
}

class Instructor <<Entity>> {
  - instructorId : guid
  - name : String
  - email : String
  + getName(): String
}

class AcademicTerm <<Entity>> {
  - termId : guid
  - name : String
  - startDate : localdate
  - endDate : localdate
  - registrationPeriodStart : localdate
  - registrationPeriodEnd : localdate
  + saveTerm(request : TermRequest): AcademicTerm
}

class CourseOffering <<Entity>> {
  - offeringId : guid
  - courseCode : String
  - section : String
  - instructorId : guid
  - termId : guid
  - meetingSchedule : MeetingSchedule
  - capacity : Capacity
  - status : OfferingStatus
  + findPublished(criteria : SearchCriteria): list<CourseOffering>
  + findById(offeringId : guid): CourseOffering
  + getDetails(): OfferingInfo
  + isRegistrationPeriodOpen(offeringId : guid): boolean
  + hasCapacity(offeringId : guid): boolean
  + conflictsWithStudentSchedule(studentId : guid, offeringId : guid): boolean
  + decrementRemainingCapacity(offeringId : guid): void
  + getById(offeringId : guid): CourseOffering
  + incrementRemainingCapacity(): void
  + enrollFromWaitlist(): void
  + getByInstructor(instructorId : guid): list<CourseOffering>
  + createOffering(request : ManageCourseOfferingRequest): CourseOffering
  + updateOffering(request : ManageCourseOfferingRequest): CourseOffering
  + publishOffering(offeringId : guid): void
  + cancelOffering(offeringId : guid): void
}

class Registration <<Entity>> {
  - registrationId : guid
  - studentId : guid
  - offeringId : guid
  - registrationDate : localdatetime
  + findByStudentAndOffering(studentId : guid, offeringId : guid): optional<Registration>
  + create(studentId : guid, offeringId : guid): Registration
  + listByStudent(studentId : guid): list<Registration>
  + findById(registrationId : guid): Registration
  + remove(): void
  + getStudentsByOffering(offeringId : guid): list<Student>
}

class WaitlistEntry <<Entity>> {
  - entryId : guid
  - studentId : guid
  - offeringId : guid
  - position : int
  - createdAt : localdatetime
  + getNextPosition(offeringId : guid): int
  + addToWaitlist(studentId : guid, offeringId : guid, position : int): WaitlistEntry
  + findByStudent(studentId : guid): list<WaitlistEntry>
  + deleteIfOwnedBy(studentId : guid, entryId : guid): boolean
}

package "Data Types" {
  class Capacity <<ValueObject>> {
    - total : int
    - remaining : int
  }
  class DropRegistrationRequest <<ValueObject>> {
    - registrationId : guid
  }
  class DropRegistrationResponse <<ValueObject>> {
    - success : boolean
    - message : String
  }
  class ExportFile <<ValueObject>> {
    - filename : String
    - content : byte[]
  }
  class JoinWaitlistRequest <<ValueObject>> {
    - studentId : guid
    - offeringId : guid
  }
  class ManageCourseOfferingRequest <<ValueObject>> {
    - offeringId : guid
    - courseCode : String
    - section : String
    - instructorId : guid
    - termId : guid
    - meetingSchedule : MeetingSchedule
    - capacity : Capacity
    - action : OfferingAction
  }
  class ManageCourseOfferingResponse <<ValueObject>> {
    - success : boolean
    - message : String
    - offeringId : guid
  }
  class MeetingSchedule <<ValueObject>> {
    - days : list<String>
    - startTime : localtime
    - endTime : localtime
    - location : String
  }
  enum OfferingAction {
    CREATE
    UPDATE
    PUBLISH
    CANCEL
  }
  class OfferingInfo <<ValueObject>> {
    - offeringId : guid
    - courseCode : String
    - section : String
    - instructorName : String
    - meetingSchedule : MeetingSchedule
    - capacity : Capacity
    - status : OfferingStatus
  }
  enum OfferingStatus {
    DRAFT
    PUBLISHED
    CANCELLED
  }
  class RegistrationResult <<ValueObject>> {
    - success : boolean
    - registrationId : optional<guid>
    - message : String
  }
  class SearchCriteria <<ValueObject>> {
    - courseCode : optional<String>
    - termId : optional<guid>
    - instructorName : optional<String>
  }
  class SearchResult <<ValueObject>> {
    - offerings : list<OfferingInfo>
    - message : optional<String>
  }
  class StudentSchedule <<ValueObject>> {
    - offerings : list<OfferingInfo>
  }
  class TermRequest <<ValueObject>> {
    - termId : guid
    - name : String
    - startDate : localdate
    - endDate : localdate
    - registrationPeriodStart : localdate
    - registrationPeriodEnd : localdate
  }
  class TermResult <<ValueObject>> {
    - success : boolean
    - message : String
    - termId : guid
  }
  class ValidationResult <<ValueObject>> {
    - eligible : boolean
    - failureReason : optional<String>
  }
}

