artifacts.deployment_diagram:
@startuml
!theme plain
left to right direction
skinparam shadowing false
skinparam linetype ortho
skinparam nodesep 55
skinparam ranksep 65
skinparam ArrowColor #2f6b50
skinparam node {
  BackgroundColor #ffffff
  BorderColor #68736b
}
skinparam rectangle {
  BackgroundColor #f8faf8
  BorderColor #68736b
}
skinparam cloud {
  BackgroundColor #f5f7f4
  BorderColor #7f8d83
}
title Runtime deployment - AWS / ap-northeast-2
actor "Internet client" as internet_client
cloud "AWS" as provider_boundary {
  frame "Region: ap-northeast-2" as region_boundary {
    node "VPC" as provider_network {
      node "Application Subnet\none selected zone" as provider_subnet {
        node "EC2 Instance\n1 standalone instance" as primary_compute {
          component "University Registration System\n<<Docker container>>\n[runtime contract]\n[mount] /var/lib/easydep/data\n[secret] SPRING_SECURITY_USER_PASSWORD\n[env] SPRING_DATASOURCE_URL\n[env] SPRING_DATASOURCE_USERNAME\n[env] SPRING_DATASOURCE_PASSWORD\n[env] SPRING_SECURITY_USER_NAME\n[image] digest binding" as runtime_application
        }
      }
      rectangle "Security Group / Application\nCompute: University Registration System" as traffic_filter_traffic_filter_compute_1 <<traffic policy>>
    }
    node "Elastic IP" as public_address
    database "EBS Volume" as persistent_disk <<retained>>
  }
}

actor "User-run deploy.sh\n<<local CSP authentication>>" as user_deploy
frame "Application delivery dependencies" as delivery_dependencies {
  cloud "VM outbound path\n(public address or managed NAT)" as workload_outbound_dependency
  node "Amazon ECR Repository" as application_registry_dependency_application
  node "IAM Role / VM Registry Pull" as application_identity_dependency_application
  artifact "University Registration System image source" as application_source_artifact_application
  artifact "University Registration System image@sha256\n<<immutable digest>>" as application_image_dependency_application
}
user_deploy -[#2f6b50]-> application_registry_dependency_application : create
user_deploy -[#2f6b50]-> application_image_dependency_application : push
application_registry_dependency_application -[#2f6b50]-> application_image_dependency_application
application_identity_dependency_application ..[#8a6d3b]> application_image_dependency_application : pull
application_source_artifact_application -[#2f6b50]-> application_image_dependency_application : build
frame "Secret runtime dependencies" as secret_dependencies {
  artifact "Existing AWS Secret" as secret_secret_ref_application_security_password
  node "IAM Role Policy / State Secret Read" as secret_binding_secret_access_binding_application_security_password
}
interface "Public HTTP endpoint" as public_endpoint
internet_client -[#2f6b50]-> public_endpoint : HTTP
public_endpoint -[#2f6b50]-> public_address
application_image_dependency_application -[#2f6b50]-> runtime_application
workload_outbound_dependency ..[#8a6d3b]> runtime_application
secret_secret_ref_application_security_password --[#8a6d3b] application_identity_dependency_application : read permission
application_identity_dependency_application ..[#8a6d3b]> runtime_application : inject
traffic_filter_traffic_filter_compute_1 ..[#8a6d3b]> runtime_application
persistent_disk ..[#6f7c73]> runtime_application
legend bottom
  |= Line |= Meaning |
  | <color:#2f6b50>solid arrow</color> | runtime request or data flow |
  | <color:#8a6d3b>dotted arrow</color> | health or traffic policy configuration |
  | <color:#6f7c73>dotted arrow</color> | placement or attachment |
endlegend
@enduml

